{"code": "import collections
import os

def get_words():
    word_file = '/usr/share/dict/words'
    if not os.path.exists(word_file):
        return set()
    with open(word_file, 'r') as f:
        words = {line.strip().upper() for line in f if len(line.strip()) == 5}
    return words

def find_ladder(start, end):
    words = get_words()
    if end not in words:
        words.add(end) # Ensure target is in dictionary
    queue = collections.deque([[start]])
    visited = {start}

    while queue:
        path = queue.popleft()
        current_word = path[-1]

        if current_word == end:
            return path

        for i in range(len(current_word)):
            for char in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
                next_word = current_word[:i] + char + current_word[i+1:]
                if next_word in words and next_word not in visited:
                    visited.add(next_word)
                    queue.append(path + [next_word])
    return None

path = find_ladder('PEDAL', 'SERUM')
print(path)"}

